"use client";
import { RETURN_POLICY } from "@/lib/return-policy";
import PreorderNotice from "@/components/PreorderNotice";
import { preorderCopy } from "@/lib/preorder-copy";

import { useEffect, useState } from "react";
import Image from "next/image";
import Link from "next/link";
import { cartStockLimit } from "@/lib/cart-stock-limit";
import { useCart } from "@/components/CartContext";
import { formatMAD } from "@/lib/products";
import { useSettings } from "@/lib/use-settings";
import { useCartCalculation } from "@/lib/use-cart-calculation";
import { calculateShipping, effectiveFreeShippingMinimum, shippingConfigFromSettings } from "@/lib/shipping-config";
import { resolveProductVariantImage } from "@/lib/product-variant-image";

export default function CartPage() {
  const { items, total, count, setQty, remove, clear, inventoryNotice, dismissInventoryNotice } = useCart();
  const siteSettings = useSettings();
  const shippingConfig = shippingConfigFromSettings(siteSettings);
  const shippingCost = shippingConfig.cost;
  const freeShippingThreshold = shippingConfig.freeThreshold;
  const freeShippingMinimum = effectiveFreeShippingMinimum(freeShippingThreshold);
  const hasFreeShippingGoal = freeShippingThreshold > 0;
  const freeShippingRemaining = hasFreeShippingGoal ? Math.max(0, freeShippingMinimum - total) : 0;
  const freeShippingUnlocked = hasFreeShippingGoal && freeShippingRemaining === 0;
  const freeShippingProgress = hasFreeShippingGoal
    ? Math.min(100, Math.max(0, (total / freeShippingMinimum) * 100))
    : 0;

  const [promoInput, setPromoInput] = useState("");
  const [promoApplied, setPromoApplied] = useState<null | {
    id: string;
    code: string;
    type: "percent" | "fixed";
    value: number;
    label: string;
    discount: number;
    excludedItemsCount: number;
    excludedSubtotal: number;
  }>(null);
  const [promoError, setPromoError] = useState("");
  const [promoOpen, setPromoOpen] = useState(false);
  const [promoLoading, setPromoLoading] = useState(false);
  const [confirmClear, setConfirmClear] = useState(false);

  const serverPricing = useCartCalculation({ items: items.map(item => ({ slug: item.slug, quantity: item.quantity, price: item.price, color: item.color, size: item.size })), couponId: promoApplied?.id }, siteSettings);
  const shipping = serverPricing.quote?.shipping ?? 0;
  const discount = serverPricing.quote?.discount ?? 0;
  const grandTotal = serverPricing.quote?.total ?? 0;

  async function applyPromo() {
    const code = promoInput.trim().toUpperCase();
    if (!code) return;
    setPromoLoading(true);
    setPromoError("");
    try {
      const res = await fetch("/api/coupons/validate/", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          code,
          items: items.map((item) => ({ slug: item.slug, quantity: item.quantity })),
        }),
      });
      const data = await res.json();
      if (!res.ok) {
        setPromoError(data.error || "Code invalide ou inactif");
        setPromoApplied(null);
      } else {
        const label = data.type === "percent" ? `-${data.value}%` : `-${data.value} MAD`;
        setPromoApplied({
          id: data.id,
          code: data.code,
          type: data.type,
          value: data.value,
          label,
          discount: data.discount,
          excludedItemsCount: data.excluded_items_count ?? 0,
          excludedSubtotal: data.excluded_subtotal ?? 0,
        });
        setPromoError("");
        setPromoInput("");
      }
    } catch {
      setPromoError("Une erreur est survenue, veuillez réessayer.");
    } finally {
      setPromoLoading(false);
    }
  }

  function removePromo() {
    setPromoApplied(null);
    setPromoError("");
    setPromoInput("");
  }

  // Keep an applied coupon accurate when quantities or cart lines change.
  useEffect(() => {
    if (!promoApplied) return;
    if (items.length === 0) {
      setPromoApplied(null);
      return;
    }

    const controller = new AbortController();
    fetch("/api/coupons/validate/", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      signal: controller.signal,
      body: JSON.stringify({
        code: promoApplied.code,
        items: items.map((item) => ({ slug: item.slug, quantity: item.quantity })),
      }),
    })
      .then(async (response) => ({ response, data: await response.json() }))
      .then(({ response, data }) => {
        if (!response.ok) {
          setPromoApplied(null);
          setPromoError(data.error || "Le code promo n'est plus applicable.");
          return;
        }
        setPromoApplied((current) => current ? {
          ...current,
          discount: data.discount,
          excludedItemsCount: data.excluded_items_count ?? 0,
          excludedSubtotal: data.excluded_subtotal ?? 0,
        } : null);
      })
      .catch((error: unknown) => {
        if (error instanceof DOMException && error.name === "AbortError") return;
        setPromoError("Impossible de recalculer le code promo.");
      });

    return () => controller.abort();
  // Revalidate only when the cart itself changes; updating promoApplied is the result.
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [items]);

  return (
    <div className="min-h-[60vh] bg-[#f7f7f8]">
      {inventoryNotice && (
        <div role="status" className="border-b border-amber-200 bg-amber-50">
          <div className="mx-auto flex max-w-7xl items-start gap-3 px-4 py-3 text-xs text-amber-900 md:px-6">
            <span aria-hidden="true" className="mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-amber-200 font-black">!</span>
            <p className="flex-1 font-semibold leading-5">{inventoryNotice}</p>
            <button type="button" onClick={dismissInventoryNotice} aria-label="Fermer le message" className="min-h-8 px-2 font-black text-amber-700 hover:text-black">×</button>
          </div>
        </div>
      )}
      {/* Breadcrumb */}
      <div className="border-b border-neutral-100 bg-white">
        <nav aria-label="Fil d’Ariane" className="mx-auto flex max-w-7xl items-center px-4 py-3.5 md:px-6">
          <ol className="flex items-center gap-2 text-[12px]">
            <li>
              <Link
                href="/"
                className="group inline-flex min-h-8 items-center gap-2 rounded-lg px-2 text-neutral-500 transition-colors hover:bg-neutral-50 hover:text-neutral-950"
              >
                <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" aria-hidden="true" className="text-neutral-400 transition-colors group-hover:text-[#179b38]">
                  <path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-7H9v7H4a1 1 0 0 1-1-1V10Z" />
                </svg>
                <span>Accueil</span>
              </Link>
            </li>
            <li aria-hidden="true" className="text-neutral-300">
              <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="m9 18 6-6-6-6" /></svg>
            </li>
            <li aria-current="page" className="font-bold text-neutral-950">Panier</li>
          </ol>
        </nav>
      </div>

      {/* Checkout progress only matters once the customer has an item to buy. */}
      {items.length > 0 && (
      <div className="bg-white border-b border-neutral-100 overflow-hidden">
        <style>{`
          @keyframes stepPulse {
            0%, 100% { box-shadow: 0 0 0 0 rgba(62,207,76,0.5); }
            50%       { box-shadow: 0 0 0 10px rgba(62,207,76,0); }
          }
          @keyframes stepShine {
            0%   { transform: translateX(-100%) skewX(-20deg); opacity: 0; }
            40%  { opacity: 0.6; }
            100% { transform: translateX(250%) skewX(-20deg); opacity: 0; }
          }
          @keyframes lineGrow {
            from { transform: scaleX(0); }
            to   { transform: scaleX(1); }
          }
          @keyframes stepBounce {
            0%, 100% { transform: translateY(0); }
            40%      { transform: translateY(-4px); }
            60%      { transform: translateY(-2px); }
          }
          .step-active-circle {
            animation: stepPulse 2s ease-in-out infinite, stepBounce 2.4s ease-in-out infinite;
          }
          .step-active-shine::after {
            content: '';
            position: absolute;
            inset: 0;
            background: linear-gradient(90deg, transparent, rgba(255,255,255,0.55), transparent);
            border-radius: 9999px;
            animation: stepShine 2.2s ease-in-out infinite;
          }
          .step-connector-fill {
            transform-origin: left;
            animation: lineGrow 0.6s ease-out forwards;
          }
          @media (prefers-reduced-motion: reduce) {
            .step-active-circle,
            .step-active-shine::after,
            .step-connector-fill {
              animation: none !important;
            }
          }
        `}</style>
        <div className="max-w-3xl mx-auto px-4 py-5 flex items-center justify-center gap-0">
          {[
            { n: 1, label: "PANIER" },
            { n: 2, label: "PAIEMENT" },
            { n: 3, label: "CONFIRMATION" },
          ].map((step, idx) => (
            <div key={step.n} className="flex items-center">
              <div className="flex flex-col items-center gap-1.5">
                <div
                  className={`relative w-9 h-9 rounded-full flex items-center justify-center text-[13px] font-black border-2 transition-all overflow-hidden ${
                    step.n === 1
                      ? "bg-[#3ecf4c] border-[#3ecf4c] text-white step-active-circle step-active-shine"
                      : "bg-white border-neutral-200 text-neutral-400"
                  }`}
                >
                  {step.n}
                </div>
                <span className={`text-[10px] tracking-[0.15em] font-black transition-colors ${step.n === 1 ? "text-[#3ecf4c]" : "text-neutral-300"}`}>
                  {step.label}
                </span>
              </div>
              {idx < 2 && (
                <div className="w-16 md:w-28 h-[2px] bg-neutral-100 mx-2 mb-5 relative overflow-hidden">
                  {step.n === 1 && (
                    <div className="absolute inset-0 step-connector-fill" style={{ background: "linear-gradient(90deg, #3ecf4c, #6bdd6b)" }} />
                  )}
                </div>
              )}
            </div>
          ))}
        </div>
      </div>
      )}

      <div className="max-w-7xl mx-auto px-4 md:px-6 py-8 sm:py-10">
        {items.length === 0 ? (
          <section className="empty-cart-enter mx-auto max-w-5xl overflow-hidden rounded-3xl border border-neutral-200 bg-white shadow-[0_18px_55px_rgba(0,0,0,.06)]">
            <div className="grid items-center gap-8 px-6 py-10 sm:px-10 sm:py-12 lg:grid-cols-[1fr_220px] lg:px-14">
              <div>
                <div className="mb-4 flex items-center gap-3">
                  <span className="h-px w-7 bg-[#3ecf4c]" />
                  <p className="text-[9px] font-black uppercase tracking-[0.26em] text-[#239f37]">Votre panier · 0 article</p>
                </div>
                <h1 className="max-w-xl text-[2.2rem] font-black leading-[1.02] tracking-[-0.045em] text-neutral-950 sm:text-[2.8rem]">
                  Votre panier est vide.
                </h1>
                <p className="mt-4 max-w-lg text-[13px] leading-6 text-neutral-500 sm:text-sm">
                  Découvrez nos collections et ajoutez les articles qui vous plaisent.
                </p>

                <div className="mt-7 flex flex-col gap-3 sm:flex-row sm:items-center">
                  <Link href="/boutique" className="group inline-flex min-h-12 items-center justify-center gap-3 rounded-xl bg-neutral-950 px-6 text-[11px] font-black uppercase tracking-[0.09em] text-white transition-all hover:bg-[#239f37] active:scale-[0.98]">
                    Découvrir la boutique
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="transition-transform group-hover:translate-x-0.5" aria-hidden="true"><path d="M5 12h14M13 6l6 6-6 6" /></svg>
                  </Link>
                  <Link href="/nouveautes" className="inline-flex min-h-12 items-center justify-center px-4 text-[11px] font-black text-neutral-600 transition-colors hover:text-neutral-950">
                    Voir les nouveautés
                  </Link>
                </div>

                <div className="mt-8 flex flex-wrap gap-x-6 gap-y-3 border-t border-neutral-100 pt-5 text-[10px] font-bold text-neutral-500">
                  <span className="inline-flex items-center gap-2"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#239f37" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/><path d="m9 12 2 2 4-4"/></svg>Paiement sécurisé</span>
                  <span className="inline-flex items-center gap-2"><svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="#239f37" strokeWidth="2.2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 12a9 9 0 1 0 3-6.7"/><path d="M3 3v6h6"/></svg>{RETURN_POLICY.summary}</span>
                </div>
              </div>

              <div className="order-first flex justify-center lg:order-none lg:justify-end">
                <div className="relative flex h-36 w-36 items-center justify-center rounded-[28px] border border-neutral-200 bg-neutral-50 text-neutral-900 sm:h-40 sm:w-40">
                  <svg width="58" height="58" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.35" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                    <path d="M3 4h2.2l1.8 10.1a2 2 0 0 0 2 1.65h8.85a2 2 0 0 0 1.96-1.58L21.3 7H6" />
                    <circle cx="9.3" cy="19.5" r="1.05"/><circle cx="18.2" cy="19.5" r="1.05"/>
                  </svg>
                  <span className="absolute -right-2 -top-2 flex h-8 w-8 items-center justify-center rounded-full border-4 border-white bg-[#3ecf4c] text-[10px] font-black text-black">0</span>
                </div>
              </div>
            </div>

            <div className="border-t border-neutral-100 bg-neutral-50/60 px-5 py-6 sm:px-8">
              <div className="mb-4 flex items-end justify-between gap-4">
                <div><p className="text-[9px] font-black uppercase tracking-[0.22em] text-[#239f37]">Collections</p><h2 className="mt-1 text-[15px] font-black text-neutral-950">Acheter par catégorie</h2></div>
                <Link href="/boutique" className="text-[10px] font-black text-neutral-500 transition-colors hover:text-black">Tout voir →</Link>
              </div>
              <nav aria-label="Catégories populaires" className="grid grid-cols-2 gap-2.5 sm:grid-cols-4">
                {[
                  { label: "Homme", href: "/homme", image: "/images/menu%20category/homme.png", position: "50% 18%" },
                  { label: "Femme", href: "/femme", image: "/images/menu%20category/femme.png", position: "50% 15%" },
                  { label: "Chaussures", href: "/chaussures", image: "/images/menu%20category/chaussures.png", position: "50% 50%" },
                  { label: "Accessoires", href: "/accessoires", image: "/images/menu%20category/accessoires.png", position: "50% 50%" },
                ].map((category, index) => (
                  <Link key={category.href} href={category.href} className="empty-cart-category group flex items-center gap-3 rounded-xl border border-neutral-200 bg-white p-2 transition-all hover:border-neutral-300 hover:shadow-sm" style={{ animationDelay: `${250 + index * 70}ms` }}>
                    <span className="relative h-14 w-16 shrink-0 overflow-hidden rounded-lg bg-neutral-100">
                      <Image src={category.image} alt="" fill sizes="64px" className="object-cover transition-transform duration-500 group-hover:scale-105" style={{ objectPosition: category.position }} />
                    </span>
                    <span className="min-w-0 flex-1 truncate text-[11px] font-black text-neutral-800">{category.label}</span>
                    <span className="mr-1 text-sm text-neutral-300 transition-all group-hover:translate-x-0.5 group-hover:text-neutral-900">→</span>
                  </Link>
                ))}
              </nav>
            </div>
          </section>
        ) : (
          <div className="grid lg:grid-cols-[1fr_380px] gap-6 items-start">
            {/* ── LEFT: Items ── */}
            <div className="bg-white rounded-xl border border-neutral-200 overflow-hidden">
              {/* Cart heading row */}
              <div className="flex items-center justify-between px-6 py-4 border-b border-neutral-100">
                <div className="flex items-center gap-2">
                  <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-neutral-700">
                    <circle cx="9" cy="21" r="1"/><circle cx="20" cy="21" r="1"/>
                    <path d="M1 1h4l2.68 13.39a2 2 0 002 1.61h9.72a2 2 0 002-1.61L23 6H6"/>
                  </svg>
                  <span className="font-black text-[15px]">Mon panier</span>
                  <span className="ml-1 w-6 h-6 rounded-full text-white text-[11px] font-black flex items-center justify-center" style={{ background: "#3ecf4c", color: "#000" }}>
                    {count}
                  </span>
                </div>
                <Link
                  href="/"
                  className="text-[12px] text-neutral-500 hover:text-black transition-colors font-semibold flex items-center gap-1.5"
                >
                  <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M19 12H5M12 19l-7-7 7-7"/></svg>
                  Continuer les achats
                </Link>
              </div>

              {/* Free-shipping progress */}
              {hasFreeShippingGoal ? (
                <div className={`border-b px-5 py-4 sm:px-6 ${freeShippingUnlocked ? "border-emerald-100 bg-emerald-50/50" : "border-neutral-100 bg-white"}`} aria-live="polite">
                  <div className="flex items-center justify-between gap-4">
                    <div className="flex min-w-0 items-center gap-3">
                      <span className={`flex h-9 w-9 shrink-0 items-center justify-center rounded-full ${freeShippingUnlocked ? "bg-emerald-600 text-white" : "bg-emerald-50 text-emerald-600"}`}>
                        {freeShippingUnlocked ? (
                          <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.7" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="m5 12 4 4L19 6"/></svg>
                        ) : (
                          <svg width="17" height="17" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true"><path d="M3 6h11v10H3zM14 9h4l3 3v4h-7z"/><circle cx="7" cy="18" r="2"/><circle cx="18" cy="18" r="2"/></svg>
                        )}
                      </span>
                      <div className="min-w-0">
                        <p className="text-[10px] font-semibold text-neutral-500">Livraison offerte dès {formatMAD(freeShippingThreshold)}</p>
                        <p className={`mt-0.5 text-[13px] font-black leading-5 sm:text-[14px] ${freeShippingUnlocked ? "text-emerald-700" : "text-neutral-950"}`}>
                          {freeShippingUnlocked ? "Votre livraison est offerte" : <>Encore {formatMAD(freeShippingRemaining)} pour en profiter</>}
                        </p>
                      </div>
                    </div>
                    <span className={`shrink-0 text-[10px] font-bold tabular-nums ${freeShippingUnlocked ? "text-emerald-700" : "text-neutral-400"}`}>
                      {freeShippingUnlocked ? "Atteint" : `${formatMAD(total)} / ${formatMAD(freeShippingThreshold)}`}
                    </span>
                  </div>

                  <div
                    className="mt-3 h-1.5 overflow-hidden rounded-full bg-neutral-100"
                    role="progressbar"
                    aria-label="Progression vers la livraison gratuite"
                    aria-valuemin={0}
                    aria-valuemax={freeShippingMinimum}
                    aria-valuenow={Math.min(total, freeShippingMinimum)}
                  >
                    <div
                      className="h-full rounded-full bg-emerald-500 transition-[width] duration-500 ease-out"
                      style={{ width: `${freeShippingProgress}%` }}
                    />
                  </div>

                  <div className="mt-2 flex items-center justify-between gap-3 text-[9px] font-medium text-neutral-400">
                    <span>{freeShippingUnlocked ? `${formatMAD(shippingCost)} économisés sur cette commande` : `Économisez ${formatMAD(shippingCost)} de livraison`}</span>
                    {!freeShippingUnlocked && (
                      <Link href="/boutique" className="shrink-0 font-bold text-neutral-600 underline decoration-neutral-300 underline-offset-4 transition hover:text-emerald-700">
                        Voir les articles
                      </Link>
                    )}
                  </div>
                </div>
              ) : (
                <div className="flex items-center gap-2 border-b border-[#3ecf4c]/20 bg-[#f0fdf4] px-6 py-3 text-[11px] font-black uppercase tracking-wider text-[#16a34a]">
                  <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M1 3h15v13H1z"/><path d="M16 8h4l3 3v5h-7V8z"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>
                  Livraison {shippingCost} MAD partout au Maroc
                </div>
              )}

              {/* Estimated delivery */}
              <div className="mx-4 my-3 flex items-center gap-3 rounded-xl border border-neutral-200 bg-white px-4 py-3 shadow-[0_4px_14px_rgba(0,0,0,0.04)] sm:mx-6">
                <span className="flex h-9 w-9 shrink-0 items-center justify-center text-neutral-950" aria-hidden="true">
                  <svg width="29" height="29" viewBox="0 0 32 32" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round">
                    <path d="M3 7h16v14H3zM19 12h5l5 5v4H19z"/>
                    <path d="M7 11h8M7 15h6M1 18h8"/>
                    <circle cx="8" cy="24" r="2.5"/><circle cx="24" cy="24" r="2.5"/>
                  </svg>
                </span>
                <div className="min-w-0 flex-1">
                  <div className="flex items-center gap-1.5">
                    <p className="text-[12px] font-semibold text-neutral-600 sm:text-[13px]">Livraison estimée</p>
                    <span className="flex h-4 w-4 items-center justify-center rounded-full border border-neutral-400 text-[9px] font-black text-neutral-600" title="Le délai commence après confirmation de la commande" aria-label="Le délai commence après confirmation de la commande">i</span>
                  </div>
                  <p className="mt-0.5 text-[14px] font-black leading-5 text-emerald-600 sm:text-[15px]">{items.some(item => item.fulfillment_type === "PREORDER") ? preorderCopy.fr.delivery : `Chez vous sous ${shippingConfig.estimatedDays}`}</p>
                </div>
                <span className="hidden shrink-0 text-[9px] font-semibold text-neutral-400 sm:block">Partout au Maroc</span>
              </div>

              {/* Column headers */}
              <div className="hidden md:grid grid-cols-[1fr_100px_120px_100px] px-6 py-3 border-b border-neutral-100 text-[10px] font-black uppercase tracking-[0.15em] text-neutral-400">
                <span>Produit</span>
                <span className="text-center">Prix</span>
                <span className="text-center">Quantité</span>
                <span className="text-right">Total</span>
              </div>

              {/* Items */}
              <ul className="divide-y divide-neutral-100">
                {items.map((i) => {
                  const displayImage = resolveProductVariantImage({ slug: i.slug, color: i.color, fallback: i.image });
                  return (
                  <li key={i.slug + i.size + i.color} className="px-6 py-5 grid grid-cols-[72px_1fr] md:grid-cols-[72px_1fr_100px_120px_100px] gap-4 items-center">
                    {/* Image */}
                    <Link href={`/produit/${i.slug}`} className="relative block w-[72px] h-[90px] bg-neutral-50 rounded-lg overflow-hidden group shrink-0">
                      <Image src={displayImage} alt={i.name} fill sizes="72px" className="object-cover group-hover:scale-105 transition-transform duration-500"/>
                    </Link>
                    {/* Name + size */}
                    <div className="min-w-0">
                      <Link href={`/produit/${i.slug}`} className="font-bold text-[13px] leading-snug hover:text-neutral-600 transition-colors line-clamp-2">{i.name}</Link><PreorderNotice item={i} />
                      <p className="text-[11px] text-neutral-400 mt-0.5 uppercase tracking-wide">
                        {i.size && i.size !== "Taille unique" ? `Taille : ${i.size}` : ""}
                        {i.size && i.size !== "Taille unique" && i.color ? " · " : ""}
                        {i.color ? `Couleur : ${i.color}` : ""}
                        {(!i.color && i.size === "Taille unique") ? "Taille unique" : ""}
                      </p>
                      {/* Mobile: qty stepper + price + remove */}
                      <div className="flex items-center gap-3 mt-2.5 md:hidden">
                        <div className="inline-flex border border-neutral-200 rounded-lg overflow-hidden">
                          <button onClick={() => setQty(i.slug, i.size, i.color, i.quantity - 1)} className="w-8 h-8 flex items-center justify-center text-base font-light hover:bg-neutral-50 transition-colors">−</button>
                          <span className="w-9 h-8 flex items-center justify-center text-[13px] font-black border-x border-neutral-200">{i.quantity}</span>
                          <button disabled={i.quantity >= cartStockLimit(i.available_stock, i.preorder_enabled)} aria-label="Augmenter la quantité" onClick={() => setQty(i.slug, i.size, i.color, i.quantity + 1)} className="disabled:opacity-30 disabled:cursor-not-allowed w-8 h-8 flex items-center justify-center text-base font-light hover:bg-neutral-50 transition-colors">+</button>
                        </div>
                        <span className="text-[13px] font-black">{formatMAD(i.price * i.quantity)}</span>
                        <button onClick={() => remove(i.slug, i.size, i.color)} className="ml-auto text-neutral-300 hover:text-red-400 transition-colors" aria-label="Retirer">
                          <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                        </button>
                      </div>
                    </div>
                    {/* Unit price (desktop) */}
                    <span className="hidden md:block text-center text-[13px] font-semibold text-neutral-700">{formatMAD(i.price)}</span>
                    {/* Qty stepper */}
                    <div className="hidden md:flex items-center justify-center">
                      <div className="inline-flex border border-neutral-200 rounded-lg overflow-hidden">
                        <button onClick={() => setQty(i.slug, i.size, i.color, i.quantity - 1)} className="w-8 h-8 flex items-center justify-center text-base font-light hover:bg-neutral-50 transition-colors">−</button>
                        <span className="w-9 h-8 flex items-center justify-center text-[13px] font-black border-x border-neutral-200">{i.quantity}</span>
                        <button disabled={i.quantity >= cartStockLimit(i.available_stock, i.preorder_enabled)} aria-label="Augmenter la quantité" onClick={() => setQty(i.slug, i.size, i.color, i.quantity + 1)} className="disabled:opacity-30 disabled:cursor-not-allowed w-8 h-8 flex items-center justify-center text-base font-light hover:bg-neutral-50 transition-colors">+</button>
                      </div>
                    </div>
                    {/* Row total + remove (desktop) */}
                    <div className="hidden md:flex flex-col items-end gap-1.5">
                      <span className="text-[14px] font-black">{formatMAD(i.price * i.quantity)}</span>
                      <button onClick={() => remove(i.slug, i.size, i.color)} className="text-neutral-300 hover:text-red-400 transition-colors" aria-label="Retirer">
                        <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                      </button>
                    </div>
                  </li>
                  );
                })}
              </ul>

              {/* Footer */}
              <div className="px-6 py-4 border-t border-neutral-100 flex items-center justify-between min-h-[54px]">
                {confirmClear ? (
                  <div className="flex flex-wrap sm:flex-nowrap items-center gap-2.5 w-full rounded-xl border border-red-100 bg-red-50/60 px-3 py-2">
                    <span className="flex items-center gap-2 text-[12px] text-neutral-700 font-bold flex-1 min-w-[150px]">
                      <span className="flex h-7 w-7 shrink-0 items-center justify-center rounded-full bg-red-100 text-red-500">
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.3" strokeLinecap="round" strokeLinejoin="round"><path d="M12 9v4"/><path d="M12 17h.01"/><path d="M10.3 3.8 2.2 18a2 2 0 0 0 1.7 3h16.2a2 2 0 0 0 1.7-3L13.7 3.8a2 2 0 0 0-3.4 0Z"/></svg>
                      </span>
                      Vider tout le panier ?
                    </span>
                    <button
                      onClick={() => { clear(); setConfirmClear(false); }}
                      className="px-3.5 py-2 text-[10px] font-black uppercase tracking-[0.1em] bg-red-500 text-white rounded-lg shadow-sm hover:bg-red-600 active:scale-[0.97] transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-red-400 focus-visible:ring-offset-2"
                    >
                      Confirmer
                    </button>
                    <button
                      onClick={() => setConfirmClear(false)}
                      className="px-3.5 py-2 text-[10px] font-black uppercase tracking-[0.1em] border border-neutral-200 bg-white text-neutral-500 rounded-lg hover:border-neutral-400 hover:text-black active:scale-[0.97] transition-all focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-neutral-300 focus-visible:ring-offset-2"
                    >
                      Annuler
                    </button>
                  </div>
                ) : (
                  <>
                    <span className="text-xs font-medium text-neutral-500">{count} article{count !== 1 ? "s" : ""}</span>
                    <button
                      type="button"
                      onClick={() => setConfirmClear(true)}
                      aria-label="Vider tous les articles du panier"
                      className="group inline-flex min-h-11 shrink-0 items-center justify-center gap-2 rounded-md px-2 py-2 text-[13px] font-medium text-neutral-500 transition-colors duration-150 hover:text-red-700 active:text-red-800 focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-neutral-800 focus-visible:ring-offset-4 motion-reduce:transition-none"
                    >
                      <span aria-hidden="true" className="flex shrink-0 items-center justify-center text-neutral-400 transition-colors duration-150 group-hover:text-red-600 motion-reduce:transition-none">
                        <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round" strokeLinejoin="round">
                          <polyline points="3 6 5 6 21 6"/>
                          <path d="M19 6l-1 14H6L5 6"/>
                          <path d="M10 11v6M14 11v6"/>
                          <path d="M9 6V4h6v2"/>
                        </svg>
                      </span>
                      <span className="border-b border-neutral-300 pb-0.5 leading-5 transition-colors duration-150 group-hover:border-red-300 motion-reduce:transition-none">Vider le panier</span>
                    </button>
                  </>
                )}
              </div>
            </div>

            {/* ── RIGHT: Summary ── */}
            <aside className="sticky top-24 space-y-4">
              <div className="bg-white rounded-xl border border-neutral-200 overflow-hidden">
                {/* Header */}
                <div className="px-6 py-4 border-b border-neutral-100 flex items-center justify-between">
                  <h2 className="font-black text-[13px] uppercase tracking-[0.15em]">Récapitulatif</h2>
                  <span className="text-[11px] text-neutral-400">{count} article{count !== 1 ? "s" : ""}</span>
                </div>

                <div className="px-6 py-5 space-y-3">
                  {/* Sous-total */}
                  <div className="flex justify-between text-[13px] text-neutral-600">
                    <span>Sous-total</span>
                    <span className="font-bold text-black">{formatMAD(total)}</span>
                  </div>

                  {/* Livraison */}
                  <div className="flex justify-between text-[13px] text-neutral-600">
                    <span>Livraison</span>
                    <span className="font-bold">
                      {shipping === 0
                        ? <span className="text-[#16a34a] flex items-center gap-1">
                            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><path d="M1 3h15v13H1z"/><path d="M16 8h4l3 3v5h-7V8z"/><circle cx="5.5" cy="18.5" r="2.5"/><circle cx="18.5" cy="18.5" r="2.5"/></svg>
                            Gratuite
                          </span>
                        : formatMAD(shipping)}
                    </span>
                  </div>

                  {/* Promo discount line */}
                  {siteSettings.enable_coupons !== "false" && promoApplied && (
                    <div className="flex justify-between text-[13px]">
                      <span className="flex items-center gap-1.5 text-[#16a34a] font-bold">
                        <svg width="12" height="12" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M20 6 9 17l-5-5"/></svg>
                        Code {promoApplied.code}
                        <span className="text-[10px] font-black px-1.5 py-0.5 rounded" style={{ background: "#f0fdf4", color: "#16a34a" }}>{promoApplied.label}</span>
                      </span>
                      <span className="font-bold text-[#16a34a]">−{formatMAD(discount)}</span>
                    </div>
                  )}

                  {/* ── Promo code input ── */}
                  {siteSettings.enable_coupons !== "false" && <div className="pt-1">
                    {!promoApplied ? (
                      <div>
                        <button
                          onClick={() => setPromoOpen(o => !o)}
                          className="flex items-center gap-1.5 text-[12px] text-neutral-500 hover:text-black transition-colors font-semibold w-full"
                        >
                          <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round">
                            <path d="M21.5 12.5l-9-9a2 2 0 00-1.4-.5H4a2 2 0 00-2 2v7.1a2 2 0 00.5 1.4l9 9a2 2 0 002.8 0l7.2-7.2a2 2 0 000-2.8z"/>
                            <circle cx="8" cy="8" r="1" fill="currentColor" stroke="none"/>
                          </svg>
                          Vous avez un code promo ?
                          <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" className={`ml-auto transition-transform duration-200 ${promoOpen ? "rotate-180" : ""}`}><path d="m6 9 6 6 6-6"/></svg>
                        </button>

                        {promoOpen && (
                          <div className="mt-3 flex gap-2">
                            <input
                              type="text"
                              value={promoInput}
                              onChange={e => { setPromoInput(e.target.value.toUpperCase()); setPromoError(""); }}
                              onKeyDown={e => e.key === "Enter" && applyPromo()}
                              placeholder="CODE PROMO"
                              className="flex-1 border border-neutral-200 rounded-lg px-3 py-2.5 text-[12px] font-bold uppercase tracking-wider outline-none focus:border-[#3ecf4c] transition-colors placeholder:text-neutral-300"
                            />
                            <button
                              onClick={applyPromo}
                              disabled={promoLoading}
                              className="px-4 py-2.5 text-[12px] font-black uppercase tracking-wide rounded-lg transition-colors disabled:opacity-60"
                              style={{ background: "#000", color: "#fff" }}
                            >
                              {promoLoading ? "..." : "OK"}
                            </button>
                          </div>
                        )}
                        {promoOpen && (
                          <p className="mt-2 flex items-start gap-1.5 text-[10px] font-medium leading-relaxed text-neutral-400">
                            <svg className="mt-0.5 shrink-0" width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><circle cx="12" cy="12" r="9"/><path d="M12 11v5M12 8h.01"/></svg>
                            Les codes promo s&apos;appliquent uniquement aux articles qui ne sont pas déjà en promotion.
                          </p>
                        )}
                        {promoError && (
                          <p className="mt-2 text-[11px] text-red-500 font-semibold flex items-center gap-1">
                            <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><circle cx="12" cy="12" r="10"/><path d="M12 8v4M12 16h.01"/></svg>
                            {promoError}
                          </p>
                        )}
                      </div>
                    ) : (
                      <div className="rounded-lg px-3 py-2.5" style={{ background: "#f0fdf4", border: "1px solid rgba(62,207,76,0.3)" }}>
                        <div className="flex items-center justify-between">
                          <span className="text-[12px] font-black text-[#16a34a] flex items-center gap-1.5">
                            <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5"><path d="M20 6 9 17l-5-5"/></svg>
                            {promoApplied.code} appliqué
                          </span>
                          <button onClick={removePromo} aria-label="Retirer le code promo" className="text-neutral-400 hover:text-red-500 transition-colors">
                            <svg width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                          </button>
                        </div>
                        {promoApplied.excludedItemsCount > 0 && (
                          <p className="mt-2 border-t border-emerald-200/70 pt-2 text-[10px] font-semibold leading-relaxed text-amber-700">
                            {promoApplied.excludedItemsCount} article{promoApplied.excludedItemsCount > 1 ? "s" : ""} déjà en promotion exclu{promoApplied.excludedItemsCount > 1 ? "s" : ""} du code ({formatMAD(promoApplied.excludedSubtotal)}).
                          </p>
                        )}
                      </div>
                    )}
                  </div>}

                  {/* Total */}
                  <div className="flex justify-between items-center pt-3 mt-1 border-t border-neutral-100">
                    <span className="font-black text-[15px]">Total TTC</span>
                    <div className="text-right">
                      {discount > 0 && (
                        <div className="text-[12px] text-neutral-400 line-through">{formatMAD(total + shipping)}</div>
                      )}
                      <span className="font-black text-[22px]" style={{ color: "#3ecf4c" }}>{serverPricing.quote ? formatMAD(grandTotal) : "—"}</span>
                    </div>
                  </div>
                </div>

                {/* CTA */}
                <div className="px-6 pb-6">
                  <Link
                    href="/checkout"
                    className="w-full flex items-center justify-center gap-2 py-4 font-black uppercase text-[12px] tracking-[0.15em] rounded-xl hover:opacity-90 active:scale-[0.98] transition-all shadow-md"
                    style={{ background: "#000", color: "#fff", boxShadow: "0 4px 20px rgba(0,0,0,0.18)" }}
                  >
                    <svg width="14" height="14" viewBox="0 0 24 24" fill="currentColor"><rect x="3" y="11" width="18" height="11" rx="2" ry="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4" fill="none" stroke="currentColor" strokeWidth="2"/></svg>
                    Procéder au paiement
                  </Link>

                  <p className="text-center text-[11px] text-neutral-400 mt-3 flex items-center justify-center gap-1.5">
                    <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" className="text-[#3ecf4c]"><path d="M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z"/></svg>
                    Paiement sécurisé · {freeShippingThreshold > 0 ? `Livraison gratuite dès ${freeShippingThreshold} MAD` : `Livraison ${shippingCost} MAD`}
                  </p>
                </div>
              </div>

              {/* Trust badges card */}
              <div className="bg-white rounded-xl border border-neutral-200 px-5 py-4 space-y-3">
                {[
                  { icon: "M3 12l2-2m0 0l7-7 7 7M5 10v10a1 1 0 001 1h3m10-11l2 2m-2-2v10a1 1 0 01-1 1h-3m-6 0a1 1 0 001-1v-4a1 1 0 011-1h2a1 1 0 011 1v4a1 1 0 001 1m-6 0h6", label: RETURN_POLICY.summary },
                  { icon: "M1 3h15v13H1zM16 8h4l3 3v5h-7V8z", label: items.some(item => item.fulfillment_type === "PREORDER") ? preorderCopy.fr.delivery : `Livraison sous ${shippingConfig.estimatedDays}` },
                  { icon: "M12 22s8-4 8-10V5l-8-3-8 3v7c0 6 8 10 8 10z", label: "Paiement à réception" },
                ].map(t => (
                  <div key={t.label} className="flex items-center gap-2.5 text-[12px] text-neutral-600">
                    <span className="w-7 h-7 rounded-full flex items-center justify-center shrink-0" style={{ background: "rgba(62,207,76,0.12)" }}>
                      <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" style={{ color: "#3ecf4c" }}><path d={t.icon}/></svg>
                    </span>
                    {t.label}
                  </div>
                ))}
              </div>
            </aside>
          </div>
        )}
      </div>
    </div>
  );
}
